-- SkillForge gamified learning session extension.
-- Mission and activity definitions are generated by controlled application logic.

create or replace function public.validate_activity_attempt()
returns trigger
language plpgsql
security invoker
set search_path = public
as $$
declare
  session_learner_id uuid;
  activity_max_xp integer;
begin
  select ls.learner_id, sa.max_xp
  into session_learner_id, activity_max_xp
  from public.session_activities sa
  join public.session_missions sm on sm.id = sa.mission_id
  join public.learning_sessions ls on ls.id = sm.session_id
  where sa.id = new.activity_id;

  if session_learner_id is null or new.student_id <> session_learner_id then
    raise exception 'Activity attempt student must be the learning session learner';
  end if;

  if new.xp_earned > activity_max_xp then
    raise exception 'Activity attempt XP cannot exceed the activity max_xp';
  end if;

  return new;
end;
$$;

create or replace function public.prevent_activity_attempt_protected_change()
returns trigger
language plpgsql
security invoker
set search_path = public
as $$
begin
  if new.id is distinct from old.id
    or new.activity_id is distinct from old.activity_id
    or new.student_id is distinct from old.student_id
    or new.attempt_number is distinct from old.attempt_number
    or new.answer is distinct from old.answer
    or new.submitted_at is distinct from old.submitted_at then
    raise exception 'Activity attempt ownership and student-authored fields cannot be changed';
  end if;

  if auth.uid() = old.student_id
    and (
      new.score is distinct from old.score
      or new.passed is distinct from old.passed
      or new.xp_earned is distinct from old.xp_earned
      or new.status is distinct from old.status
      or new.teacher_feedback is distinct from old.teacher_feedback
      or new.reviewed_by is distinct from old.reviewed_by
      or new.reviewed_at is distinct from old.reviewed_at
    ) then
    raise exception 'Students cannot modify activity review or XP fields';
  end if;

  return new;
end;
$$;

create table public.session_missions (
  id uuid primary key default gen_random_uuid(),
  session_id uuid not null
    references public.learning_sessions(id) on delete cascade,
  title text not null,
  description text,
  learning_goal text,
  total_xp integer not null default 0 check (total_xp >= 0),
  status text not null default 'not_started' check (
    status in ('not_started', 'in_progress', 'completed', 'failed')
  ),
  started_at timestamptz,
  completed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (session_id)
);

create table public.session_activities (
  id uuid primary key default gen_random_uuid(),
  mission_id uuid not null
    references public.session_missions(id) on delete cascade,
  sequence_number integer not null check (sequence_number > 0),
  title text not null,
  activity_type text not null check (
    activity_type in ('quiz', 'problem_solving', 'practice', 'final_challenge')
  ),
  instructions text,
  content jsonb not null default '{}'::jsonb,
  max_xp integer not null default 0 check (max_xp >= 0),
  requires_teacher_review boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (mission_id, sequence_number)
);

create table public.activity_attempts (
  id uuid primary key default gen_random_uuid(),
  activity_id uuid not null
    references public.session_activities(id) on delete cascade,
  student_id uuid not null
    references public.profiles(id) on delete cascade,
  attempt_number integer not null check (attempt_number > 0),
  answer jsonb not null default '{}'::jsonb,
  score numeric check (score is null or score >= 0),
  passed boolean,
  xp_earned integer not null default 0 check (xp_earned >= 0),
  status text not null default 'submitted' check (
    status in ('submitted', 'passed', 'needs_retry', 'reviewed')
  ),
  teacher_feedback text,
  reviewed_by uuid references public.profiles(id) on delete set null,
  reviewed_at timestamptz,
  submitted_at timestamptz not null default now(),
  unique (activity_id, student_id, attempt_number)
);

create table public.student_xp (
  student_id uuid primary key
    references public.profiles(id) on delete cascade,
  total_xp integer not null default 0 check (total_xp >= 0),
  level integer not null default 1 check (level >= 1),
  updated_at timestamptz not null default now()
);

create table public.credit_transactions (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null
    references public.profiles(id) on delete cascade,
  amount integer not null check (amount <> 0),
  transaction_type text not null check (
    transaction_type in ('mission_reward', 'session_request', 'refund', 'adjustment')
  ),
  description text not null,
  reference_type text,
  reference_id uuid,
  created_at timestamptz not null default now()
);

create trigger session_missions_set_updated_at
before update on public.session_missions
for each row execute function public.set_updated_at();

create trigger session_activities_set_updated_at
before update on public.session_activities
for each row execute function public.set_updated_at();

create trigger student_xp_set_updated_at
before update on public.student_xp
for each row execute function public.set_updated_at();

create trigger validate_activity_attempt_before_write
before insert or update on public.activity_attempts
for each row execute function public.validate_activity_attempt();

create trigger prevent_activity_attempt_protected_change
before update on public.activity_attempts
for each row execute function public.prevent_activity_attempt_protected_change();

-- UNIQUE(session_id) and UNIQUE(mission_id, sequence_number) already provide
-- the equivalent indexes for those lookup paths.
create index idx_session_missions_status
  on public.session_missions(status);
create index idx_activity_attempts_activity_student
  on public.activity_attempts(activity_id, student_id);
create index idx_activity_attempts_student_id
  on public.activity_attempts(student_id);
create index idx_activity_attempts_reviewed_by
  on public.activity_attempts(reviewed_by);
create index idx_student_xp_total_xp
  on public.student_xp(total_xp);
create index idx_credit_transactions_student_created
  on public.credit_transactions(student_id, created_at);
create index idx_credit_transactions_reference
  on public.credit_transactions(reference_type, reference_id);

alter table public.session_missions enable row level security;
alter table public.session_activities enable row level security;
alter table public.activity_attempts enable row level security;
alter table public.student_xp enable row level security;
alter table public.credit_transactions enable row level security;

create policy session_missions_select_participant
on public.session_missions for select to authenticated
using (
  exists (
    select 1
    from public.learning_sessions ls
    where ls.id = session_missions.session_id
      and (ls.learner_id = auth.uid() or ls.teacher_id = auth.uid())
  )
);

create policy session_activities_select_participant
on public.session_activities for select to authenticated
using (
  exists (
    select 1
    from public.session_missions sm
    join public.learning_sessions ls on ls.id = sm.session_id
    where sm.id = session_activities.mission_id
      and (ls.learner_id = auth.uid() or ls.teacher_id = auth.uid())
  )
);

create policy activity_attempts_select_own_or_teacher
on public.activity_attempts for select to authenticated
using (
  exists (
    select 1
    from public.session_activities sa
    join public.session_missions sm on sm.id = sa.mission_id
    join public.learning_sessions ls on ls.id = sm.session_id
    where sa.id = activity_attempts.activity_id
      and (
        (activity_attempts.student_id = auth.uid() and ls.learner_id = auth.uid())
        or ls.teacher_id = auth.uid()
      )
  )
);

create policy activity_attempts_insert_own
on public.activity_attempts for insert to authenticated
with check (
  student_id = auth.uid()
  and status = 'submitted'
  and xp_earned = 0
  and score is null
  and passed is null
  and teacher_feedback is null
  and reviewed_by is null
  and reviewed_at is null
  and exists (
    select 1
    from public.session_activities sa
    join public.session_missions sm on sm.id = sa.mission_id
    join public.learning_sessions ls on ls.id = sm.session_id
    where sa.id = activity_attempts.activity_id
      and ls.learner_id = auth.uid()
  )
);

create policy activity_attempts_update_teacher
on public.activity_attempts for update to authenticated
using (
  exists (
    select 1
    from public.session_activities sa
    join public.session_missions sm on sm.id = sa.mission_id
    join public.learning_sessions ls on ls.id = sm.session_id
    where sa.id = activity_attempts.activity_id
      and ls.teacher_id = auth.uid()
  )
)
with check (
  reviewed_by = auth.uid()
  and reviewed_at is not null
  and exists (
    select 1
    from public.session_activities sa
    join public.session_missions sm on sm.id = sa.mission_id
    join public.learning_sessions ls on ls.id = sm.session_id
    where sa.id = activity_attempts.activity_id
      and ls.teacher_id = auth.uid()
  )
);

create policy student_xp_select_own
on public.student_xp for select to authenticated
using (student_id = auth.uid());

create policy credit_transactions_select_own
on public.credit_transactions for select to authenticated
using (student_id = auth.uid());
